24	export type Step = QuoteStep | ClaimStep;
25	
26	export interface Scenario {
27	  customer: { yearsWithMHPCO: number };
28	  steps: Step[];
29	}
30	
31	export interface QuoteResult {
32	  premium: number;
33	}
34	
