40	export interface ScenarioResults {
41	  results: (QuoteResult | ClaimResult)[];
42	}
43	
44	const PROCESSING_FEE = 5;
45	const FIRST_INSURANCE_SURCHARGE = 0.1;
46	
47	const BASE_PREMIUMS: Record<string, number> = {
48	  sword: 100,
49	  amulet: 60,
50	};
51	
52	const quotePremium = (items: Item[]): number => {
53	  const basePremium = items.reduce(
54	    (sum, item) => sum + BASE_PREMIUMS[item.type],
55	    0,
56	  );
57	  return (
58	    basePremium + basePremium * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE
59	  );
60	};
61	
62	export const runScenario = (scenario: Scenario): ScenarioResults => ({
63	  results: scenario.steps.map((step) => ({
64	    premium: quotePremium((step as QuoteStep).items),
65	  })),
66	});
